output_text:
[
  {
    "id": "must_return_cart_to_bay",
    "text": "Before leaving, the shopper must park the cart in the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "cart_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "park_cart_at_return_bay": {
          "pre": {
            "and": [
              "hasCart",
              "at_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "park_cart_at_return_bay"
    }
  },
  {
    "id": "no_cart_drop_outside_bay",
    "text": "A shopper may not leave a cart anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "at_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_while_pushing_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_pushing_cart"
    }
  },
  {
    "id": "no_carts_in_exit_zone",
    "text": "Shopping carts are not allowed in the exit or checkout zone near the lower-right side of the store.",
    "abstraction": {
      "state_properties": {
        "exit_zone": {
          "or": [
            "at(7,5)",
            "at(8,5)",
            "at(9,5)",
            "at(8,4)",
            "at(9,4)",
            "at(9,3)"
          ]
        },
        "cart_in_exit_zone": {
          "and": [
            "hasCart",
            "exit_zone"
          ]
        }
      },
      "events": {
        "be_in_exit_zone_with_cart": {
          "pre": "cart_in_exit_zone",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_zone"
    }
  },
  {
    "id": "must_take_entry_cart",
    "text": "A shopper must take the available entry cart before beginning the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_available": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items may only be picked up while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "shopping_with_cart": "hasCart",
        "shopping_without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "shopping_without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Loose items must not be carried by hand; they should be transported in the cart instead.",
    "abstraction": {
      "state_properties": {
        "loose_item_in_hand": "handFull",
        "no_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "no_cart"
            ]
          },
          "post": "loose_item_in_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "loose_item_in_hand",
          "become_hand_full"
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "After returning the cart to the bay, the shopper must not resume store interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_bay": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_store_interaction": {
          "pre": {
            "and": [
              "cart_returned_to_bay",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_store_interaction"
    }
  }
]
